-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Social Sciences — Geography
-- Course outlines transcribed from the Faculty of Social Sciences course
-- handbook (scanned copy), covering the Four-Year Standard Undergraduate
-- Programme (B.Sc) in Geography: all four years, both semesters, including
-- required ancillary, general-studies and elective courses.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for this department are removed first, so it updates rather than duplicates.
--
-- SEMESTERS: the handbook explicitly labels every course "FIRST SEMESTER" or
-- "SECOND SEMESTER" in its programme-structure tables, so those stated values
-- are used directly — no guessing was needed here.
--
-- The 400-level programme splits into two elective option tracks each
-- semester — "Physical Resources Options" and "Human Geography and Spatial
-- Management Options" — both are included in full as the standard timetable
-- offers both, not one student's chosen track.
--
-- Two course-description headings in the source were faintly printed such
-- that a digit was hard to read against the surrounding structure table:
-- "GEO 323/333: Application(s) of Geographic Information Systems" is filed
-- under GEO 333 (the code the programme-structure table clearly lists at
-- 300 Level); "GEO 453/483: The Developing World" is filed under GEO 483
-- (matching the description heading, since the structure table's own digit
-- was the less legible of the two).
--
-- GEO 311 (Principles of Hydrology), GEO 313 (Runoff Processes in Drainage
-- Basins), GEO 335 (Environmental Remote Sensing), GEO 337 (Aerial Photo
-- Interpretation), GEO 353 (Land Resource Evaluation) and GEO 363 (Soil
-- Conservation and Protection) have real descriptions printed in the source
-- but were not found in any programme-structure table captured from this
-- scan, so their level/semester/unit placement cannot be verified — they are
-- left out rather than guessed at.
--
-- ANCILLARY/GSP/ELECTIVE COURSES FROM OTHER DEPARTMENTS: courses such as
-- ECO 1xx/2xx, PSY 1xx/2xx, SOC 1xx, PSC 1xx, ANT 102/303, COS 101/304,
-- GSP 1xx/2xx, MTH 111/112/113 and GLG 103/141 appear in the Geography
-- timetable but their own descriptions are not printed in the Geography
-- section of this document, so they carry real code/title/units only, with
-- description left blank pending a verified source elsewhere in this app.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Geography';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('GEO 101', 'Basic Elements of Landforms and the Hydrosphere', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'first', 2, 'Solar system. The earth in space. Structure and composition of the Earth. Internal structures and processes of the Earth. Classification of rocks. Sedimentary, igneous, metamorphic, Geomorphic cycle. The hydrological cycle and landforms - Endogenic and Exogenic. Erosional cycles. The drainage system and patterns. Coastal landforms. Ocean currents.', '["Solar system. The earth in space. Structure and composition of the Earth", "Internal structures and processes of the Earth", "Classification of rocks: Sedimentary, igneous, metamorphic", "Geomorphic cycle", "The hydrological cycle and landforms - Endogenic and Exogenic. Erosional cycles", "The drainage system and patterns", "Coastal landforms. Ocean currents"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 103', 'Fundamentals of Human Geography I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'first', 2, 'Definition, nature and scope of Human Geography. Man and his Environment: population, growth and distribution. Human population characteristics. Types of human settlements. Elements of behavioural geography. Elements of Cultural Geography. Culture change. Religion, Gender and culture. Elements of Political Geography. Geographic characteristics of states. Boundaries.', '["Definition, nature and scope of Human Geography", "Man and his Environment: population, growth and distribution", "Human population characteristics. Types of human settlements", "Elements of behavioural geography", "Elements of Cultural Geography. Culture change. Religion, Gender and culture", "Elements of Political Geography. Geographic characteristics of states. Boundaries"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 121', 'Basic Statistical Methods for Geographers I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'first', 2, 'The nature of geographic data. Measurement and compilation of geographic information. Frequency distributions. Graphical Presentation of Geographic Data. Measures of central tendency and dispersion. The normal distribution and probability assessments. The binomial distribution. Sample and population parameters. Methods of sampling.', '["The nature of geographic data. Measurement and compilation of geographic information", "Frequency distributions. Graphical Presentation of Geographic Data", "Measures of central tendency and dispersion", "The normal distribution and probability assessments. The binomial distribution", "Sample and population parameters. Methods of sampling"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 131', 'Introduction to Mapwork and Practical Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'first', 2, 'Types of maps. Scales, Grid systems and Grid references. Bearings. Conventional symbols. Map reduction and enlargement. Areas and distances. Map reading: identification and interpretation of features of relief, drainage, vegetation and human occupance. Interpretation of maps of selected areas.', '["Types of maps. Scales, Grid systems and Grid references. Bearings", "Conventional symbols. Map reduction and enlargement", "Areas and distances", "Map reading: identification and interpretation of features of relief, drainage, vegetation and human occupance", "Interpretation of maps of selected areas"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 161', 'Introduction to Environmental Science', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'first', 2, 'Nature and scope of man-environment problems. Natural hazards: geomorphic, fluvial atmospheric and biological. Man-made environmental problems. Meaning and types of wastes. Wastes Disposal methods.', '["Nature and scope of man-environment problems", "Natural hazards: geomorphic, fluvial atmospheric and biological", "Man-made environmental problems", "Meaning and types of wastes. Wastes Disposal methods"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 102', 'Basic Elements of the Atmosphere and Biosphere', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'second', 2, 'Composition of the atmosphere. Solar radiation. Temperature and atmospheric pressure. The global wind system. Humidity and precipitation. Climates of the continents. Soils: formation, characteristics, development and classification. Distribution of Natural vegetation characteristics, classification and distribution.', '["Composition of the atmosphere. Solar radiation. Temperature and atmospheric pressure", "The global wind system. Humidity and precipitation", "Climates of the continents", "Soils: formation, characteristics, development and classification", "Distribution of Natural vegetation characteristics, classification and distribution"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 104', 'Fundamentals of Human Geography II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'second', 2, 'Primary economic activities. Secondary economic activities. Tertiary economic activities. Spatial patterns of distribution of man''s socio-economic activities. Spatial patterns and interaction processes especially patterns of world trade and transportation.', '["Primary economic activities", "Secondary economic activities", "Tertiary economic activities", "Spatial patterns of distribution of man''s socio-economic activities", "Spatial patterns and interaction processes especially patterns of world trade and transportation"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 122', 'Basic Statistical Methods for Geographers II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'second', 2, 'Statistical Significance Tests. The Null and Alternate hypotheses. Comparisons and significance of sample values. The Students ''t'' test. The Chi-square test. Spearman''s Rank and Pearson''s Product Moment Correlation and significance tests. Linear Regression, Prediction and Standard Errors. Analysis of residuals.', '["Statistical Significance Tests. The Null and Alternate hypotheses", "Comparisons and significance of sample values", "The Students ''t'' test. The Chi-square test", "Spearman''s Rank and Pearson''s Product Moment Correlation and significance tests", "Linear Regression, Prediction and Standard Errors", "Analysis of residuals"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 132', 'Elementary Surveying', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'second', 3, 'Introduction to surveying. Basic surveying systems and instrumentation. Techniques of elementary surveying: chain, compass, plane table. Adjustment of closing errors.', '["Introduction to surveying. Basic surveying systems and instrumentation", "Techniques of elementary surveying: chain, compass, plane table", "Adjustment of closing errors"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 184', 'Local Field Studies', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'second', 3, 'Class/Field studies to familiarize students with their local environment as an adjunct to their classroom lectures in physical and human geography. A day field work to examine various physical (environmental) and human problems within Nsukka region. Investigation of the relationship among urbanization, development, agricultural activities and environment. The course is examined solely on the submitted reports.', '["Class/Field studies to familiarize students with their local environment as an adjunct to their classroom lectures in physical and human geography", "A day field work to examine various physical (environmental) and human problems within Nsukka region", "Investigation of the relationship among urbanization, development, agricultural activities and environment", "The course is examined solely on the submitted reports"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 162', 'Basics of Environmental Change', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '100 Level', 'second', 2, 'Global human population: size, distribution and growth rate. Form and pattern of resource consumption. Technologies used to produce and consume resources. Climate change. Linkages among the environmental issues. Environmental disasters.', '["Global human population: size, distribution and growth rate", "Form and pattern of resource consumption", "Technologies used to produce and consume resources", "Climate change", "Linkages among the environmental issues", "Environmental disasters"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 201', 'Contemporary Philosophy and Methodology of Geography I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'first', 2, 'Geography as a science. Ancient and Medieval Geography. Determinism, possibilism and the new geography. Regional and systematic methodology. Conceptual and methodological dualisms in Geography. Radical Philosophies in Geography. Paradigm and Paradigm Shifts in Geography.', '["Geography as a science. Ancient and Medieval Geography", "Determinism, possibilism and the new geography", "Regional and systematic methodology", "Conceptual and methodological dualisms in Geography", "Radical Philosophies in Geography", "Paradigm and Paradigm Shifts in Geography"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 211', 'Development and Structural Basis of Geomorphology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'first', 2, 'The nature and scope of geomorphology. The structure of the earth and composition of the earth''s crust. The geologic time scale. The nature and classification of rocks. Earth movements. Faults and associated landforms. Folding and associated land forms, Volcanicity: volcanic landscapes and man. Block and other diagrams.', '["The nature and scope of geomorphology", "The structure of the earth and composition of the earth''s crust", "The geologic time scale. The nature and classification of rocks", "Earth movements. Faults and associated landforms", "Folding and associated land forms, Volcanicity: volcanic landscapes and man", "Block and other diagrams"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 213', 'The Physical Basis of Climate', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'first', 2, 'Nature and scope of climatology. Composition of the atmosphere. Radiation and the heat budget. Measurements of weather elements. Weather maps, charts. Atmospheric temperature, pressure and motion. The general circulation. Upper air currents. Oceanic circulations. Evaporation and atmospheric moisture. Adiabatic processes. Cloud formation and genera. The formation of precipitation.', '["Nature and scope of climatology. Composition of the atmosphere", "Radiation and the heat budget. Measurements of weather elements", "Weather maps, charts. Atmospheric temperature, pressure and motion", "The general circulation. Upper air currents. Oceanic circulations", "Evaporation and atmospheric moisture. Adiabatic processes", "Cloud formation and genera. The formation of precipitation"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 215', 'Introduction to Biogeography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'first', 2, 'Nature, scope, aims and objectives of biogeography and biodiversity. Development of biogeography. Biogeographical classification. Scope and nature of phytogeography. Scope and nature of zoogeography. Factors and processes of soil formation. Soil properties and soil classification. Nigerian soils. Soil erosion. The concept of ecosystems and ecological communities. Soil and vegetation surveys and mapping. Climate change and biogeography.', '["Nature, scope, aims and objectives of biogeography and biodiversity", "Development of biogeography. Biogeographical classification", "Scope and nature of phytogeography. Scope and nature of zoogeography", "Factors and processes of soil formation. Soil properties and soil classification. Nigerian soils. Soil erosion", "The concept of ecosystems and ecological communities", "Soil and vegetation surveys and mapping. Climate change and biogeography"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 231', 'Introduction to Cartography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'first', 2, 'Nature and scope of cartography. The development of cartography. Modern maps and their classification. Introduction to map projections. Cylindrical, azimuthal, conical and miscellaneous projections: construction, properties, limitations. Spherical, rectangular and plane co-ordinate systems. Cartographic instruments and equipment. Basics of graphics and typography. Lettering techniques.', '["Nature and scope of cartography. The development of cartography", "Modern maps and their classification", "Introduction to map projections. Cylindrical, azimuthal, conical and miscellaneous projections: construction, properties, limitations", "Spherical, rectangular and plane co-ordinate systems", "Cartographic instruments and equipment", "Basics of graphics and typography. Lettering techniques"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 271', 'Spatial Patterns of Land Use', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'first', 2, 'Land use: definition and explanation of the concept. Determinants of land use. Basic introduction to the following: national policy on the environment. EIA Act. Land use Act. NESREA Act. NOSDRA Act. Climate change Act. Major classes of land use- rural and urban. Models of rural/agricultural land use. Models of urban land use and land use zoning. Land use mapping - qualitative and quantitative using aerial/satellite photographs and remotely sensed images. Land quality and regional development planning. Fieldwork land use/land cover mapping and land use control and management.', '["Land use: definition and explanation of the concept. Determinants of land use", "National policy on the environment. EIA Act. Land use Act. NESREA Act. NOSDRA Act. Climate change Act", "Major classes of land use- rural and urban", "Models of rural/agricultural land use. Models of urban land use and land use zoning", "Land use mapping - qualitative and quantitative using aerial/satellite photographs and remotely sensed images", "Land quality and regional development planning", "Fieldwork land use/land cover mapping and land use control and management"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 202', 'Contemporary Philosophy and Methodology of Geography II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'second', 2, 'The scientific method in geography. Explanation in geography. Quantification, models, laws and theories in geography. Systems analysis in geography. Schools of Geography - French, German, American, British and Nigerian. Sustainability and Sustainable Development and Careers for Geographers.', '["The scientific method in geography. Explanation in geography", "Quantification, models, laws and theories in geography", "Systems analysis in geography", "Schools of Geography - French, German, American, British and Nigerian", "Sustainability and Sustainable Development and Careers for Geographers"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 212', 'Geomorphological Processes and Forms', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'second', 2, 'Geomorphic process. Weathering. Mass wasting. Slope form and development. Morphometric analysis. The effects of rocks on relief, Karst topography. Landforms of arid and semi-arid regions. Humid tropical landforms. Glacial and periglacial landforms. Coastal landforms. An introduction to applied geomorphology.', '["Geomorphic process. Weathering. Mass wasting", "Slope form and development. Morphometric analysis", "The effects of rocks on relief, Karst topography", "Landforms of arid and semi-arid regions", "Humid tropical landforms. Glacial and periglacial landforms. Coastal landforms", "An introduction to applied geomorphology"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 214', 'Climatic Systems and Regional Climates', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'second', 2, 'The thunderstorm. Extra-tropical and tropical synoptic disturbances. Coastal, topographical and urban effects on climate. Climatic classification: the work of Koppen, Miller and others. The climate of West Africa. Theories of climatic change. Adverse and inadvertent modifications of climate. Introduction to applied climatology. Measurement of climatic elements.', '["The thunderstorm. Extra-tropical and tropical synoptic disturbances", "Coastal, topographical and urban effects on climate", "Climatic classification: the work of Koppen, Miller and others", "The climate of West Africa", "Theories of climatic change. Adverse and inadvertent modifications of climate", "Introduction to applied climatology. Measurement of climatic elements"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 216', 'Principles of Biogeography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'second', 2, 'Factors of distribution of plants and animals. Climate change impacts on the distribution of biodiversity. Biochores of the world: forest, savanna, grassland and desert. Vegetation dynamics, succession and climaxes. Phytosociology and biocenosis. General characteristics and distribution of animal life. Zoogeographical regions of the world. Zoosociology and biocenotic integration. The nature of ecological communities. Food chains; energy flows and biogeochemical cycles. Carrying capacity and population control. Terrestrial and aquatic ecosystems.', '["Factors of distribution of plants and animals. Climate change impacts on the distribution of biodiversity", "Biochores of the world: forest, savanna, grassland and desert. Vegetation dynamics, succession and climaxes", "Phytosociology and biocenosis", "General characteristics and distribution of animal life. Zoogeographical regions of the world", "Zoosociology and biocenotic integration. The nature of ecological communities", "Food chains; energy flows and biogeochemical cycles", "Carrying capacity and population control. Terrestrial and aquatic ecosystems"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 222', 'Statistical Inference from Geographic Data', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'second', 2, 'Tests of hypotheses. Comparing means and frequency distributions. The Mann-Whitney and Kolmogorov-Smirnov tests. Point patterns and quadrat analysis. Nearest neighbour and centrographic techniques. Analysis of variance: ANOVA, MANOVA. Geography and time. Elements of time series analysis. Analysis of spatial interaction.', '["Tests of hypotheses. Comparing means and frequency distributions", "The Mann-Whitney and Kolmogorov-Smirnov tests", "Point patterns and quadrat analysis. Nearest neighbour and centrographic techniques", "Analysis of variance: ANOVA, MANOVA", "Geography and time. Elements of time series analysis", "Analysis of spatial interaction"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 234', 'Introduction to Geographic Information Systems', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'second', 2, 'Definition and Scope of GIS. Land, airborne and satellite sensing platforms. GIS hardware: PC''s, digitizers, scanners. GIS software: Arc/Info, Arc View and other GIS UNITS packages. The nature of GIS Data. Data structures. Cartographic data banks. Geo-referencing systems.', '["Definition and Scope of GIS", "Land, airborne and satellite sensing platforms", "GIS hardware: PC''s, digitizers, scanners", "GIS software: Arc/Info, Arc View and other GIS packages", "The nature of GIS Data. Data structures", "Cartographic data banks. Geo-referencing systems"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 242', 'Introduction to Population Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '200 Level', 'second', 2, 'Theoretical foundations, nature and scope of population geography. Tools for analysis in population geography. Population growth, trend, distribution patterns and components worldwide and in Africa. Urbanization; trends, patterns and consequences. Population explosion; causes and implications. Migration processes and consequences. Race and ethnicity. Households and mutuality. The Nigerian population structure; distribution patterns and implications.', '["Theoretical foundations, nature and scope of population geography", "Tools for analysis in population geography", "Population growth, trend, distribution patterns and components worldwide and in Africa", "Urbanization; trends, patterns and consequences", "Population explosion; causes and implications", "Migration processes and consequences. Race and ethnicity", "Households and mutuality", "The Nigerian population structure; distribution patterns and implications"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 321', 'Multivariate Statistical Analysis in Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'first', 2, 'Multiple and partial correlation. Elements of matrix algebra. Multiple regression. Analysis of residuals. Geographical surfaces: trend and potential surfaces. Principal components and factor analysis: mapping and interpretation of components. loadings and scores. Classification and regionalisation in geography: graphical and numerical.', '["Multiple and partial correlation. Elements of matrix algebra", "Multiple regression. Analysis of residuals", "Geographical surfaces: trend and potential surfaces", "Principal components and factor analysis: mapping and interpretation of components, loadings and scores", "Classification and regionalisation in geography: graphical and numerical"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 333', 'Application of Geographic Information Systems', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'first', 2, 'Manipulation, management and outputs of GIS data. Integration of GIS and other data bases. Interpretation of GIS output. Applications of GIS to urban, regional, agricultural, hydrology etc. surveys. Prospects of large scale GIS utilization., map digitization.', '["Manipulation, management and outputs of GIS data", "Integration of GIS and other data bases", "Interpretation of GIS output", "Applications of GIS to urban, regional, agricultural, hydrology etc. surveys", "Prospects of large scale GIS utilization, map digitization"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 331', 'Thematic Cartography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'first', 2, 'Nature and uses of thematic maps. Qualitative distributive symbolization: positional, linear and areal qualitative mapping. Quantitative: (a) Point symbolization: mapping with dots, squares, cubes and spheres and segmented circles; (b) Line symbolization: mapping with lines and flow-line mapping, (c) Areal symbolization: Choropleth mapping. Techniques of lettering.', '["Nature and uses of thematic maps", "Qualitative distributive symbolization: positional, linear and areal qualitative mapping", "Quantitative Point symbolization: mapping with dots, squares, cubes and spheres and segmented circles", "Line symbolization: mapping with lines and flow-line mapping", "Areal symbolization: Choropleth mapping", "Techniques of lettering"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 341', 'Principles and Methods of Population Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'first', 2, 'The nature of population data. Rates and Ratios. Population censuses and other sources of population data. The life table. Checks, errors and corrections in population data. Concepts. Analysis and spatial aspects of mortality, fertility and migration. Models of population structure and change. Manpower and fertility population problems.', '["The nature of population data. Rates and Ratios. Population censuses and other sources of population data", "The life table. Checks, errors and corrections in population data", "Concepts, Analysis and spatial aspects of mortality, fertility and migration", "Models of population structure and change", "Manpower and fertility population problems"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 343', 'Settlement Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'first', 2, 'Types and functional study of rural settlements. Rural settlement systems: concepts, location, theories and processes. Types of urban settlements. Origin, growth and functions of urban settlements. Systems of urban settlements/Urban hierarchy, Rank Size Rule, Urban influence zones / Theories of urbanization. Central Place theory and applications. Interpretation of cultural variable using topographical maps. Mitigating the impact of climate change on settlement systems.', '["Types and functional study of rural settlements", "Rural settlement systems: concepts, location, theories and processes", "Types of urban settlements. Origin, growth and functions of urban settlements", "Systems of urban settlements/Urban hierarchy, Rank Size Rule, Urban influence zones", "Theories of urbanization. Central Place theory and applications", "Interpretation of cultural variable using topographical maps", "Mitigating the impact of climate change on settlement systems"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 351', 'Economic Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'first', 2, 'Theoretical foundations, scope and problems of economic geography. Resources of production: their nature, meaning and classification. Concept and dynamics of economic regions. Spatial transformation of economic concepts. Types of economic regions. The informal economy.', '["Theoretical foundations, scope and problems of economic geography", "Resources of production: their nature, meaning and classification", "Concept and dynamics of economic regions", "Spatial transformation of economic concepts", "Types of economic regions", "The informal economy"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 373', 'Geographical Regions of Africa', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'first', 2, 'Brief survey of the historical geography of Africa. The physical environment, the natural resources, the human resources, and the development of the continent. Transportation, industrialization, urbanization. The political and economic development of Western, Eastern, Northern and Southern Africa. The A.U., and the regional blocs. Problems of African Development. Climate change and African Development. Case studies.', '["Brief survey of the historical geography of Africa", "The physical environment, the natural resources, the human resources, and the development of the continent", "Transportation, industrialization, urbanization", "The political and economic development of Western, Eastern, Northern and Southern Africa", "The A.U., and the regional blocs", "Problems of African Development", "Climate change and African Development. Case studies"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 309', 'Research Design and Methodology in Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'second', 2, 'The purpose of research. Major steps in geographic research. Procedures for field investigation and data collection of features of the physical and cultural landscape. Preparation of a research proposal. Selection of analytical procedures. Problems of research in different fields of geography. The research report.', '["The purpose of research. Major steps in geographic research", "Procedures for field investigation and data collection of features of the physical and cultural landscape", "Preparation of a research proposal. Selection of analytical procedures", "Problems of research in different fields of geography", "The research report"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 384', 'Geography Field Course I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'second', 3, 'Four to seven (4-7) days of field study tour oriented to various physical and environmental geographic problems in a selected region of Nigeria. Investigation and analysis of physical data collected in the region of study. Presentation of individual reconnaissance and group reports on selected research themes. The course is examined solely on the submitted reports.', '["Four to seven (4-7) days of field study tour oriented to various physical and environmental geographic problems in a selected region of Nigeria", "Investigation and analysis of physical data collected in the region of study", "Presentation of individual reconnaissance and group reports on selected research themes", "The course is examined solely on the submitted reports"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 386', 'Geography Field Course II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'second', 3, 'Four to seven (4-7) days of field study tour oriented to various human geographic problems in a selected region of Nigeria. Investigation and analysis of human data collected in the region of study. Presentation of individual reconnaissance and group reports on selected research themes. The course is examined solely on the submitted reports.', '["Four to seven (4-7) days of field study tour oriented to various human geographic problems in a selected region of Nigeria", "Investigation and analysis of human data collected in the region of study", "Presentation of individual reconnaissance and group reports on selected research themes", "The course is examined solely on the submitted reports"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 388', '(SIWES) Students Industrial Work Experience Scheme', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '300 Level', 'second', 10, 'Six-month long Industrial work experience. SIWES log book report. Individual report on the work experience.', '["Six-month long Industrial work experience", "SIWES log book report", "Individual report on the work experience"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 411', 'Geomorphology of the Tropics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Geomorphology and climate. The Pleistocene epoch and its climatic and geomorphic changes and effects. Geomorphic processes in the tropics. Weathering, erosion, stream activity. Characteristic landforms of tropical regions. Evolution of some Nigerian landscapes.', '["Geomorphology and climate", "The Pleistocene epoch and its climatic and geomorphic changes and effects", "Geomorphic processes in the tropics. Weathering, erosion, stream activity", "Characteristic landforms of tropical regions", "Evolution of some Nigerian landscapes"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 413', 'Weather and Climate in the Tropics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Delimitation of the tropics. Radiation and temperature. Tropical circulations: the Hadley cell and trade winds. Equatorial circulations. The Asiatic monsoon. Tropical synoptic disturbances. The nature of tropical rainfall. Tropical climates: Af, Aw, Am, BSh, BWh. Climatic anomalies of the tropics. The southern oscillation and El Nino phenomena. The climate of Nigeria.', '["Delimitation of the tropics. Radiation and temperature", "Tropical circulations: the Hadley cell and trade winds. Equatorial circulations", "The Asiatic monsoon. Tropical synoptic disturbances", "The nature of tropical rainfall. Tropical climates: Af, Aw, Am, BSh, BWh", "Climatic anomalies of the tropics. The southern oscillation and El Nino phenomena", "The climate of Nigeria"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 415', 'Tropical Vegetation Resource Analysis', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Classification and distribution of tropical vegetation. Floristic characteristics and forms. Environmental and ecological relationships and controls. Evaluation and dynamics of vegetation resources. The role of man. The role of climate change in tropical vegetation resource distribution. Utilization and conservation of tropical vegetation resources. Vegetation analysis.', '["Classification and distribution of tropical vegetation. Floristic characteristics and forms", "Environmental and ecological relationships and controls", "Evaluation and dynamics of vegetation resources. The role of man", "The role of climate change in tropical vegetation resource distribution", "Utilization and conservation of tropical vegetation resources", "Vegetation analysis"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 417', 'Urban Hydrological Problems', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Urban runoff characteristics: Meaning, objectives, history. Urban flooding mechanism, causes, impacts and mitigation. Urban sedimentation, soil erosion and control in urban areas/watersheds. Urban drainage and sewage systems. Urban surface and ground water pollution and monitoring. Aquifer monitoring.', '["Urban runoff characteristics: Meaning, objectives, history", "Urban flooding mechanism, causes, impacts and mitigation", "Urban sedimentation, soil erosion and control in urban areas/watersheds", "Urban drainage and sewage systems", "Urban surface and ground water pollution and monitoring. Aquifer monitoring"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 465', 'Geography of Water Resources', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Water as a resource. Distribution of water. Properties of water. Exploitation of natural water sources. Man-made water resources: reservoirs, desalination, artificial generation of rainfall.', '["Water as a resource. Distribution of water. Properties of water", "Exploitation of natural water sources", "Man-made water resources: reservoirs, desalination, artificial generation of rainfall"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 441', 'Urbanization and Development', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'The scope and content of urban geography. World urbanization. The rise and growth of cities. Current trends in world urbanization. Cities as central places. Size and spacing of cities. Classification of cities. Cities and national development. Urban environmental problems in Nigeria.', '["The scope and content of urban geography. World urbanization", "The rise and growth of cities. Current trends in world urbanization", "Cities as central places. Size and spacing of cities", "Classification of cities", "Cities and national development", "Urban environmental problems in Nigeria"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 443', 'Rural Environment, Development and Sustainability', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Basic concepts of rural life. The rural environment and space. Rural settlements: types, patterns, changes. Rural population and depopulation. Rural economy: types, sectoral features, functioning and dynamics of change. Patterns of rural economic activity. Problems, methods and analytical processes in rural economic studies. The rural landscape: Sustainability of rural environment. Rural environment in a changing climate: vulnerability, mitigation and adaptation.', '["Basic concepts of rural life. The rural environment and space", "Rural settlements: types, patterns, changes", "Rural population and depopulation", "Rural economy: types, sectoral features, functioning and dynamics of change", "Patterns of rural economic activity", "Problems, methods and analytical processes in rural economic studies", "The rural landscape: Sustainability of rural environment", "Rural environment in a changing climate: vulnerability, mitigation and adaptation"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 447', 'Techniques and Models in Population Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Assessment of the sources of population data-population surveys, censuses, vital registration. Models of population growth, decrease and composition. Evaluation and assessment of age and sex data. Analysis and estimates of demographic phenomena, fertility estimation methods, morbidity and health status; mortality estimation. Population-environment relationships-perception, risks, vulnerability, mitigation, adaptation.', '["Assessment of the sources of population data-population surveys, censuses, vital registration", "Models of population growth, decrease and composition", "Evaluation and assessment of age and sex data", "Analysis and estimates of demographic phenomena, fertility estimation methods, morbidity and health status; mortality estimation", "Population-environment relationships-perception, risks, vulnerability, mitigation, adaptation"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 451', 'Development of Transport Systems', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Definition, Scope, and areas of research in Transport. Historical evolution of transportation as a spatial phenomenon. Transportation and spatial processes. Idealized process of transport development and its application to selected countries. Modes of transportation - development of waterways, railways, roads, airways etc. with special reference to Nigeria and other developing countries. Containerization and Inter modalism. Descriptive Interaction Models – The Gravity Model and other associated models. Transportation Networks - Optimal networks and Linear Programming.', '["Definition, Scope, and areas of research in Transport", "Historical evolution of transportation as a spatial phenomenon", "Transportation and spatial processes", "Idealized process of transport development and its application to selected countries", "Modes of transportation – development of waterways, railways, roads, airways etc. with special reference to Nigeria and other developing countries", "Containerization and Inter modalism. Descriptive Interaction Models – The Gravity Model and other associated models", "Transportation Networks - Optimal networks and Linear Programming"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 457', 'Industrial Location and Models', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Nature and scope of industrial geography. Industry in the urban area. Government regional policy. Selected case studies: iron and steel, petro-chemicals, paper, etc. Location factors. Approaches to theory: spatial economic analysis; critique and reform. Models of industrial location. Industrial linkages. Spatial margins to profitability. Critique and reforms.', '["Nature and scope of industrial geography", "Industry in the urban area. Government regional policy. Selected case studies: iron and steel, petro-chemicals, paper, etc", "Location factors", "Approaches to theory: spatial economic analysis; critique and reform", "Models of industrial location", "Industrial linkages. Spatial margins to profitability", "Critique and reforms"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 455', 'Principles of Agricultural Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Scope and methods of agricultural geography. Position of agricultural geography among the Agricultural Sciences. Pure vs practical objectives. Concern for man-environment relationships. Factors influencing agriculture. Concept of Agricultural Regions. World Agricultural Regions. Climate change Adaptation and mitigation in Agricultural systems.', '["Scope and methods of agricultural geography", "Position of agricultural geography among the Agricultural Sciences", "Pure vs practical objectives. Concern for man-environment relationships", "Factors influencing agriculture", "Concept of Agricultural Regions. World Agricultural Regions", "Climate change Adaptation and mitigation in Agricultural systems"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 475', 'Principles of Political Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Definition and scope. Approaches. The significance and concept of territory. Territoriality and traditional behaviour. The concept of conflict. The spatial factors in conflict resolution. Electoral geography; voting patterns and electoral districting. Systems approach: The balance of power between regions with national territories.', '["Definition and scope. Approaches", "The significance and concept of territory. Territoriality and traditional behaviour", "The concept of conflict. The spatial factors in conflict resolution", "Electoral geography; voting patterns and electoral districting", "Systems approach: The balance of power between regions with national territories"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 483', 'The Developing World', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'The nature of underdevelopment in the Developing World. Poverty and income distribution. Geographical distribution of natural and human resources and technology. Production systems and links with the international economy. Development strategies: Agriculture, industrialization, urbanization and man-power development. International trade and transfer of resources.', '["The nature of underdevelopment in the Developing World. Poverty and income distribution", "Geographical distribution of natural and human resources and technology", "Production systems and links with the international economy", "Development strategies: Agriculture, industrialization, urbanization and man-power development", "International trade and transfer of resources"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 471', 'Geographical Regions of Nigeria', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 3, 'Detailed outline of the physical and human environment of Nigeria: basis and systems of regionalization. Formal and functional regionalization of Nigeria. Systems perception of the functional regions of Nigeria.', '["Detailed outline of the physical and human environment of Nigeria: basis and systems of regionalization", "Formal and functional regionalization of Nigeria", "Systems perception of the functional regions of Nigeria"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 477', 'Geography in Regional Planning', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 3, 'Nature, scope and objectives of regional planning. Planning process. Theoretical basis. The role of laws and theories. Geographical conception of a region. Theory of regional development: growth poles, growth centers and growth axis. The environment as a system. Physical and human resource analyses. National resource development. Fieldwork.', '["Nature, scope and objectives of regional planning. Planning process. Theoretical basis", "The role of laws and theories. Geographical conception of a region", "Theory of regional development: growth poles, growth centers and growth axis", "The environment as a system", "Physical and human resource analyses", "National resource development. Fieldwork"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 479', 'Spatial Analysis and Modeling', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'first', 2, 'Some basic concepts of spatial interaction. Uniform regions. Functional regions. Regional specialization: agglomeration economies and comparative advantages. Bases for spatial interaction: Transferability, complementarity and Intervening opportunity. Transnational Corporations (TNCs) and the Global economy. Spatial analysis. Spatial modeling.', '["Some basic concepts of spatial interaction. Uniform regions. Functional regions", "Regional specialization: agglomeration economies and comparative advantages", "Bases for spatial interaction: Transferability, complementarity and Intervening opportunity", "Transnational Corporations (TNCs) and the Global economy", "Spatial analysis. Spatial modeling"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 412', 'Applied Geomorphology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Field techniques in geomorphology. Maps and aerial photographs in geomorphology. Laboratory methods. Geomorphological maps. G.I.S in geomorphology. Geomorphology and mineral exploration, river basin development, coastal management, transport development, urban development, agricultural development.', '["Field techniques in geomorphology. Maps and aerial photographs in geomorphology", "Laboratory methods. Geomorphological maps. G.I.S in geomorphology", "Geomorphology and mineral exploration, river basin development, coastal management, transport development, urban development, agricultural development"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 414', 'Applied Climatology', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Urban effects on climate. Urban climates. Air pollution. Evapotranspiration and the water balance. Climate and agriculture, transport, industry and architecture Drought: causes and consequences. Wind breaks and shelter belts. Climate and human comfort. Weather forecasting: types, methods and problems. Climatic change; causes, Consequences and Mitigation.', '["Urban effects on climate. Urban climates. Air pollution", "Evapotranspiration and the water balance", "Climate and agriculture, transport, industry and architecture", "Drought: causes and consequences. Wind breaks and shelter belts", "Climate and human comfort", "Weather forecasting: types, methods and problems", "Climatic change; causes, Consequences and Mitigation"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 416', 'Ecosystem Management', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'The ecosystem as a concept and its application to resource management. Approaches to Ecosystem Management. Terrestrial, aquatic and managed ecosystems structure and functional mechanisms. Disturbed ecosystems. Fire, urbanization, agricultural practices and other forms of disturbances. Ecosystem conservation and adaptation to climate change.', '["The ecosystem as a concept and its application to resource management. Approaches to Ecosystem Management", "Terrestrial, aquatic and managed ecosystems structure and functional mechanisms", "Disturbed ecosystems. Fire, urbanization, agricultural practices and other forms of disturbances", "Ecosystem conservation and adaptation to climate change"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 418', 'Hydrological Measurements and Network Design', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Urban Hydrological Problems. Precipitation measurement in Urbanized Watersheds. Measurement and empirical estimation of evaporation, evapotranspiration, infiltration and soil Moisture. Runoff and water balance models. Hydrological network design for various purposes. Well designs and sinking techniques. Aquifer control designs.', '["Urban Hydrological Problems", "Precipitation measurement in Urbanized Watersheds", "Measurement and empirical estimation of evaporation, evapotranspiration, infiltration and soil Moisture", "Runoff and water balance models", "Hydrological network design for various purposes", "Well designs and sinking techniques. Aquifer control designs"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 466', 'Water Resources Development and Management', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'The demand for water. Factors affecting water demand. Water Resources development. Water resource planning and development in Nigeria and the tropics. The social, environmental and health aspects of water resources development. Legal aspects of water resources. International drainage basin co-operation and development. Water conflict, Water resource management and conservation. Climate change and water resources development.', '["The demand for water. Factors affecting water demand. Water Resources development", "Water resource planning and development in Nigeria and the tropics", "The social, environmental and health aspects of water resources development", "Legal aspects of water resources. International drainage basin co-operation and development", "Water conflict, Water resource management and conservation", "Climate change and water resources development"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 442', 'Internal Structure of the City', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Theories and models of urban form and development. Urban land use types. The central business district; the residential neighbourhoods; other land use types; Transportation, communication, and linkages. The rural-urban fringe. Economic base of cities. Problems of rapid urban growth. Urban geography and city planning. Classification of cities. Cities and national development. Urban environmental problems in Nigeria.', '["Theories and models of urban form and development. Urban land use types", "The central business district; the residential neighbourhoods; other land use types", "Transportation, communication, and linkages. The rural-urban fringe", "Economic base of cities. Problems of rapid urban growth", "Urban geography and city planning", "Classification of cities. Cities and national development", "Urban environmental problems in Nigeria"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 444', 'Rural Development Planning', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Meaning and scope of rural development. Space use and transformation in rural development. Rural development models: empirical illustrations from the developed and underdeveloped systems. Spatial issues in rural development studies. Appraisal of rural development projects in Nigeria and other developing countries. Rural development planning with special reference to Nigeria.', '["Meaning and scope of rural development. Space use and transformation in rural development", "Rural development models: empirical illustrations from the developed and underdeveloped systems", "Spatial issues in rural development studies", "Appraisal of rural development projects in Nigeria and other developing countries", "Rural development planning with special reference to Nigeria"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 448', 'Population and Resource Development', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Assessment of the sources of population data-population surveys, censuses, vital registration. Models of population growth, decrease and composition. Evaluation and assessment of age and sex data. Analysis and estimates of demographic phenomena, fertility estimation methods, morbidity and health status; mortality estimation. Population-environment relationships-perception, risks, vulnerability, mitigation, adaptation.', '["Assessment of the sources of population data-population surveys, censuses, vital registration", "Models of population growth, decrease and composition", "Evaluation and assessment of age and sex data", "Analysis and estimates of demographic phenomena, fertility estimation methods, morbidity and health status; mortality estimation", "Population-environment relationships-perception, risks, vulnerability, mitigation, adaptation"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 452', 'Transportation Development Problems and Planning', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'The role of transportation in economic development – Case Studies of U.S.A., Nigeria, Ghana etc. The Urban transportation problem, Economic and environmental aspects of the urban transport problem. Control of the transportation data inventory, data collection, data analysis etc. Transportation planning models – Trip Generation, Trip Distribution, Modal Split and Trip Assignment models. The Rural transportation problem. Transport and ICT.', '["The role of transportation in economic development – Case Studies of U.S.A., Nigeria, Ghana etc", "The Urban transportation problem, Economic and environmental aspects of the urban transport problem", "Control of the transportation data inventory, data collection, data analysis etc", "Transportation planning models – Trip Generation, Trip Distribution, Modal Split and Trip Assignment models", "The Rural transportation problem. Transport and ICT"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 458', 'Industrial Systems and Development', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'The Spatial pattern of distribution of industries. Industry in the urban area. Government regional policy. Selected case studies: iron and steel, petro-chemicals, paper, etc. Industrial development, regional inequality and planning examples from Nigeria, Great Britain and France.', '["The Spatial pattern of distribution of industries. Industry in the urban area", "Government regional policy", "Selected case studies: iron and steel, petro-chemicals, paper, etc", "Industrial development, regional inequality and planning examples from Nigeria, Great Britain and France"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 456', 'Agricultural Resources of the Humid Tropics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Problems of delimiting the Humid Tropics for agriculture. Advantages and limitations of the humid tropics for agriculture. Farming types found within the humid tropics. Problems of crop and livestock production in Nigeria. Appraisal of some livestock production schemes in Nigeria. Vulnerability of Agricultural Resources to climate change. Mitigating climate change impact on Agricultural resources of the humid tropics.', '["Problems of delimiting the Humid Tropics for agriculture", "Advantages and limitations of the humid tropics for agriculture", "Farming types found within the humid tropics", "Problems of crop and livestock production in Nigeria", "Appraisal of some livestock production schemes in Nigeria", "Vulnerability of Agricultural Resources to climate change. Mitigating climate change impact on Agricultural resources of the humid tropics"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 476', 'The Political Organization of Space', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Boundaries and relationship among states. Jurisdictions exercised over maritime space as an extension of territory. The balance of power between nations in time of peace and war. The distribution of territory, population and resources between political systems and the recent evolution thereof: Local Government system.', '["Boundaries and relationship among states", "Jurisdictions exercised over maritime space as an extension of territory", "The balance of power between nations in time of peace and war", "The distribution of territory, population and resources between political systems and the recent evolution thereof: Local Government system"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 432', 'Advanced Cartographic Methods II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Mechanical, optical and photographic aids in cartography. Basics of map production and reproduction. Computer assisted cartographic principles, hardware and software. Development of cartography in Nigeria.', '["Mechanical, optical and photographic aids in cartography", "Basics of map production and reproduction", "Computer assisted cartographic principles, hardware and software", "Development of cartography in Nigeria"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 446', 'Theories and Applications in Population Geography', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Theories and concepts of population. Demographic transition. Demographic transition in developed and developing countries. Migration theories and applications: Everett Lee''s Push-Pull Theory, Zelinsky''s Transition Theory, Todaro''s Economic Motives Theory, Gulliver''s Bright Lights Theory etc. Population characteristics; their relevance and consequences in development planning, population projections methods; their implications for national and regional planning.', '["Theories and concepts of population. Demographic transition. Demographic transition in developed and developing countries", "Migration theories and applications: Everett Lee''s Push-Pull Theory, Zelinsky''s Transition Theory, Todaro''s Economic Motives Theory, Gulliver''s Bright Lights Theory etc", "Population characteristics; their relevance and consequences in development planning", "Population projections methods; their implications for national and regional planning"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 454', 'The Developed World', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Differentiation of the Developed Worlds. Income distribution and standards of living. Historical evolution of the developed economics. Social, economic and political framework of the capitalist and centrally planned states. Geographical bases of the economies of Western Europe, U.S.A., Russia and Japan Growth and performance of agriculture, industries and services. International trade and implication in the world economy.', '["Differentiation of the Developed Worlds. Income distribution and standards of living", "Historical evolution of the developed economics", "Social, economic and political framework of the capitalist and centrally planned states", "Geographical bases of the economies of Western Europe, U.S.A., Russia and Japan Growth and performance of agriculture, industries and services", "International trade and implication in the world economy"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 472', 'Geography of Nigeria Development', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'The physical and human settings for Nigerian development: spatial patterns of physical and human resources. Concepts and types of development. Agricultural, industrial and transport development and patterns. Internal and external trade. Energy development and prospects. Urban and rural systems. Approaches to regional development in Nigeria.', '["The physical and human settings for Nigerian development: spatial patterns of physical and human resources", "Concepts and types of development", "Agricultural, industrial and transport development and patterns", "Internal and external trade. Energy development and prospects", "Urban and rural systems", "Approaches to regional development in Nigeria"]'::jsonb, 'Department of Geography handbook'),
  ('GEO 474', 'Theories and Applications of Spatial Management', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Geography', '400 Level', 'second', 2, 'Spatial theories and Models, Spatial Analysis/modeling, Spatial Sampling, Measures of dispersion and central tendency in Spatial analysis, Regressions ,linear programming and Spatial autocorrelation, Decision support analysis, Spatial actions ,Approaches to space and environment; landscape analysis and modeling; Environment and society.', '["Spatial theories and Models, Spatial Analysis/modeling, Spatial Sampling", "Measures of dispersion and central tendency in Spatial analysis", "Regressions, linear programming and Spatial autocorrelation", "Decision support analysis, Spatial actions", "Approaches to space and environment; landscape analysis and modeling", "Environment and society"]'::jsonb, 'Department of Geography handbook'),
